import{_ as a,o as n,c as t,a as i}from"./app.DkoUFz-u.js";const d=JSON.parse('{"title":"🔑 OAuth 2.0 授权流程","description":"","frontmatter":{},"headers":[],"relativePath":"backend/auth/oauth/flows.md","filePath":"backend/auth/oauth/flows.md"}'),l={name:"backend/auth/oauth/flows.md"};function p(e,s,o,h,c,_){return n(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="🔑-oauth-2-0-授权流程" tabindex="-1">🔑 OAuth 2.0 授权流程 <a class="header-anchor" href="#🔑-oauth-2-0-授权流程" aria-label="Permalink to &quot;🔑 OAuth 2.0 授权流程&quot;">​</a></h1><h2 id="一、oauth-2-0-核心概念" tabindex="-1">一、OAuth 2.0 核心概念 <a class="header-anchor" href="#一、oauth-2-0-核心概念" aria-label="Permalink to &quot;一、OAuth 2.0 核心概念&quot;">​</a></h2><h4 id="_1-基本定义" tabindex="-1">1. 基本定义 <a class="header-anchor" href="#_1-基本定义" aria-label="Permalink to &quot;1. 基本定义&quot;">​</a></h4><p>OAuth 2.0是一种<strong>开放的授权框架</strong>（RFC 6749），允许第三方应用在获得用户授权后，代表用户访问存储在服务提供方的资源，而无需共享用户的凭证（如用户名和密码）。它专注于<strong>授权</strong>（我能做什么），而非认证（我是谁）。</p><h4 id="_2-核心角色" tabindex="-1">2. 核心角色 <a class="header-anchor" href="#_2-核心角色" aria-label="Permalink to &quot;2. 核心角色&quot;">​</a></h4><p>OAuth 2.0协议中通常包含四个主要角色：</p><ul><li><strong>资源所有者 (Resource Owner)</strong>：通常指用户，拥有授权能力的实体</li><li><strong>客户端 (Client)</strong>：代表用户访问资源的第三方应用</li><li><strong>资源服务器 (Resource Server)</strong>：托管受保护资源的服务器，能够接收并使用访问令牌来响应受保护资源请求</li><li><strong>授权服务器 (Authorization Server)</strong>：在认证资源所有者并获取授权后，向客户端颁发访问令牌</li></ul><p><strong>注意</strong>：授权服务器与资源服务器在实现上可以是同一个实体。</p><h2 id="二、oauth-2-0-四种授权流程" tabindex="-1">二、OAuth 2.0 四种授权流程 <a class="header-anchor" href="#二、oauth-2-0-四种授权流程" aria-label="Permalink to &quot;二、OAuth 2.0 四种授权流程&quot;">​</a></h2><p>OAuth 2.0定义了四种授权流程以适应不同应用场景：</p><table tabindex="0"><thead><tr><th>授权模式</th><th>适用场景</th><th>安全性</th><th>用户参与度</th></tr></thead><tbody><tr><td>授权码模式</td><td>有后端的Web应用</td><td>高</td><td>高</td></tr><tr><td>简化模式</td><td>纯前端应用(SPA)</td><td>中</td><td>高</td></tr><tr><td>密码模式</td><td>受信任的应用</td><td>低</td><td>高</td></tr><tr><td>客户端模式</td><td>应用自身权限</td><td>中</td><td>无</td></tr></tbody></table><p>下面是这四种授权流程的详细说明。</p><h4 id="_1-授权码模式" tabindex="-1">1. 授权码模式 <a class="header-anchor" href="#_1-授权码模式" aria-label="Permalink to &quot;1. 授权码模式&quot;">​</a></h4><p>这是<strong>最安全、最常用</strong>的流程，适用于有后端的Web应用。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">sequenceDiagram</span></span>
<span class="line"><span class="__shiki_140thh">    participant U as 用户</span></span>
<span class="line"><span class="__shiki_140thh">    participant C as 客户端</span></span>
<span class="line"><span class="__shiki_140thh">    participant AS as 授权服务器</span></span>
<span class="line"><span class="__shiki_140thh">    participant RS as 资源服务器</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    Note over U, C: 1. 请求授权</span></span>
<span class="line"><span class="__shiki_140thh">    U-&gt;&gt;C: 访问客户端</span></span>
<span class="line"><span class="__shiki_140thh">    C-&gt;&gt;U: 重定向到授权服务器</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    Note over U, AS: 2. 用户授权</span></span>
<span class="line"><span class="__shiki_140thh">    U-&gt;&gt;AS: 登录并授权</span></span>
<span class="line"><span class="__shiki_140thh">    AS-&gt;&gt;U: 返回授权码</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    Note over C, AS: 3. 交换令牌</span></span>
<span class="line"><span class="__shiki_140thh">    U-&gt;&gt;C: 带回授权码</span></span>
<span class="line"><span class="__shiki_140thh">    C-&gt;&gt;AS: 使用授权码请求访问令牌</span></span>
<span class="line"><span class="__shiki_140thh">    AS-&gt;&gt;C: 返回访问令牌和刷新令牌</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    Note over C, RS: 4. 访问资源</span></span>
<span class="line"><span class="__shiki_140thh">    C-&gt;&gt;RS: 使用访问令牌请求资源</span></span>
<span class="line"><span class="__shiki_140thh">    RS-&gt;&gt;C: 返回受保护资源</span></span></code></pre></div><p><strong>具体步骤</strong>：</p><ol><li><p><strong>请求授权码</strong>：客户端将用户重定向到授权服务器</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://authorization-server.com/oauth/authorize?</span></span>
<span class="line"><span class="__shiki_wvjl67">  response_type=code&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_id=CLIENT_ID&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  redirect_uri=REDIRECT_URI&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  scope=SCOPE&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  state=RANDOM_STRING</span></span></code></pre></div></li><li><p><strong>返回授权码</strong>：用户授权后，授权服务器重定向到指定URI并附带授权码</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://client.com/callback?code=AUTHORIZATION_CODE&amp;state=RANDOM_STRING</span></span></code></pre></div></li><li><p><strong>交换访问令牌</strong>：客户端使用授权码向授权服务器请求令牌</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://authorization-server.com/oauth/token?</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_id=CLIENT_ID&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_secret=CLIENT_SECRET&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  grant_type=authorization_code&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  code=AUTHORIZATION_CODE&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  redirect_uri=REDIRECT_URI</span></span></code></pre></div></li><li><p><strong>返回访问令牌</strong>：授权服务器返回访问令牌和可选的刷新令牌</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">{</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;access_token&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;ACCESS_TOKEN&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;token_type&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;bearer&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;expires_in&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_dzsirb">3600</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;refresh_token&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;REFRESH_TOKEN&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;scope&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;read&quot;</span></span>
<span class="line"><span class="__shiki_140thh">}</span></span></code></pre></div></li></ol><p><strong>安全特点</strong>：授权码在前端传输，访问令牌在后端传输，避免令牌暴露。</p><h4 id="_2-简化模式" tabindex="-1">2. 简化模式 <a class="header-anchor" href="#_2-简化模式" aria-label="Permalink to &quot;2. 简化模式&quot;">​</a></h4><p>适用于<strong>纯前端应用</strong>（如单页应用），没有后端服务器。</p><p><strong>步骤</strong>：</p><ol><li><p><strong>直接请求令牌</strong>：客户端将用户重定向到授权服务器</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://authorization-server.com/oauth/authorize?</span></span>
<span class="line"><span class="__shiki_wvjl67">  response_type=token&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_id=CLIENT_ID&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  redirect_uri=REDIRECT_URI&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  scope=read</span></span></code></pre></div></li><li><p><strong>返回访问令牌</strong>：用户授权后，授权服务器直接将令牌作为URL片段返回</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://client.com/callback#token=ACCESS_TOKEN</span></span></code></pre></div></li></ol><p><strong>安全特点</strong>：令牌直接在前端传递，安全性较低，通常令牌有效期较短。</p><h4 id="_3-密码模式" tabindex="-1">3. 密码模式 <a class="header-anchor" href="#_3-密码模式" aria-label="Permalink to &quot;3. 密码模式&quot;">​</a></h4><p>适用于<strong>高度信任的客户端</strong>，用户需要直接将凭证提供给客户端。</p><p><strong>步骤</strong>：</p><ol><li><p><strong>发送密码请求令牌</strong>：客户端直接使用用户名密码请求令牌</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://authorization-server.com/oauth/token?</span></span>
<span class="line"><span class="__shiki_wvjl67">  grant_type=password&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  username=USERNAME&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  password=PASSWORD&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_id=CLIENT_ID</span></span></code></pre></div></li><li><p><strong>返回访问令牌</strong>：授权服务器验证通过后直接返回令牌</p></li></ol><p><strong>安全特点</strong>：风险较高，需要用户完全信任客户端。</p><h4 id="_4-客户端模式" tabindex="-1">4. 客户端模式 <a class="header-anchor" href="#_4-客户端模式" aria-label="Permalink to &quot;4. 客户端模式&quot;">​</a></h4><p>适用于<strong>客户端访问自身资源</strong>而非用户资源的场景。</p><p><strong>步骤</strong>：</p><ol><li><p><strong>客户端直接请求令牌</strong>：使用客户端凭证直接请求令牌</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://authorization-server.com/oauth/token?</span></span>
<span class="line"><span class="__shiki_wvjl67">  grant_type=client_credentials&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_id=CLIENT_ID&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_secret=CLIENT_SECRET</span></span></code></pre></div></li><li><p><strong>返回访问令牌</strong>：授权服务器验证客户端身份后返回令牌</p></li></ol><p><strong>特点</strong>：不涉及用户授权，令牌针对应用而非用户。</p><h2 id="三、令牌的使用与刷新" tabindex="-1">三、令牌的使用与刷新 <a class="header-anchor" href="#三、令牌的使用与刷新" aria-label="Permalink to &quot;三、令牌的使用与刷新&quot;">​</a></h2><h4 id="_1-使用访问令牌" tabindex="-1">1. 使用访问令牌 <a class="header-anchor" href="#_1-使用访问令牌" aria-label="Permalink to &quot;1. 使用访问令牌&quot;">​</a></h4><p>获得访问令牌后，客户端通过在API请求中添加令牌来访问受保护资源：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">Authorization: Bearer ACCESS_TOKEN</span></span></code></pre></div><p>或</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://api.resource-server.com/data?access_token=ACCESS_TOKEN</span></span></code></pre></div><h4 id="_2-刷新访问令牌" tabindex="-1">2. 刷新访问令牌 <a class="header-anchor" href="#_2-刷新访问令牌" aria-label="Permalink to &quot;2. 刷新访问令牌&quot;">​</a></h4><p>当访问令牌过期时，可使用刷新令牌获取新的访问令牌：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">https://authorization-server.com/oauth/token?</span></span>
<span class="line"><span class="__shiki_wvjl67">  grant_type=refresh_token&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_id=CLIENT_ID&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  client_secret=CLIENT_SECRET&amp;</span></span>
<span class="line"><span class="__shiki_wvjl67">  refresh_token=REFRESH_TOKEN</span></span></code></pre></div><h2 id="四、实际应用示例" tabindex="-1">四、实际应用示例 <a class="header-anchor" href="#四、实际应用示例" aria-label="Permalink to &quot;四、实际应用示例&quot;">​</a></h2><h4 id="_1-微信扫码登录" tabindex="-1">1. 微信扫码登录 <a class="header-anchor" href="#_1-微信扫码登录" aria-label="Permalink to &quot;1. 微信扫码登录&quot;">​</a></h4><p>使用微信登录第三方网站的典型流程：</p><ol><li>用户点击&quot;微信登录&quot;，跳转到微信授权页面</li><li>用户扫码并同意授权，微信返回授权码</li><li>网站使用授权码向微信请求访问令牌</li><li>网站使用访问令牌获取用户基本信息</li></ol><h4 id="_2-google-oauth-2-0-配置" tabindex="-1">2. Google OAuth 2.0 配置 <a class="header-anchor" href="#_2-google-oauth-2-0-配置" aria-label="Permalink to &quot;2. Google OAuth 2.0 配置&quot;">​</a></h4><p>配置Google OAuth 2.0的基本步骤：</p><ol><li>在Google Cloud Console创建项目</li><li>配置OAuth同意屏幕</li><li>创建OAuth 2.0客户端ID和密钥</li><li>实现授权流程</li></ol><h2 id="五、安全注意事项" tabindex="-1">五、安全注意事项 <a class="header-anchor" href="#五、安全注意事项" aria-label="Permalink to &quot;五、安全注意事项&quot;">​</a></h2><ol><li><strong>state参数</strong>：用于防止CSRF攻击，在请求中传递随机值，授权服务器原样返回</li><li><strong>redirect_uri验证</strong>：确保重定向URI已注册，防止开放重定向漏洞</li><li><strong>PKCE扩展</strong>：针对公共客户端的授权码流程，增加代码验证器防止授权码拦截</li><li><strong>令牌安全存储</strong>：避免在前端存储敏感令牌，确保传输使用HTTPS</li><li><strong>范围限制</strong>：遵循最小权限原则，只请求必要的scope</li></ol><h2 id="六、开发与调试建议" tabindex="-1">六、开发与调试建议 <a class="header-anchor" href="#六、开发与调试建议" aria-label="Permalink to &quot;六、开发与调试建议&quot;">​</a></h2><ol><li><strong>使用现有库</strong>：尽可能使用官方提供的认证库，而非手动实现协议</li><li><strong>调试工具</strong>：使用Apifox等工具调试OAuth 2.0接口</li><li><strong>单页应用配置</strong>：为SPA正确配置重定向URI类型</li><li><strong>错误处理</strong>：实现完善的错误处理机制，处理各种授权失败情况</li></ol>`,53)])])}const g=a(l,[["render",p]]);export{d as __pageData,g as default};
